/** Step into a push: command a body-frame velocity along the pelvis velocity, so the policy steps under the drift. */
export class KiroReflex extends Reflex {
  /** Gain in (m/s) per (m/s) of pelvis velocity, minus the commanded velocity. */
  static gain = 1.5;

