import { Reflex, type ReflexState } from './reflex.js';

/** Step into a push: command a body-frame velocity along the pelvis velocity, so the policy steps under the drift. */
export class KiroReflex extends Reflex {
  /** Gain in (m/s) per (m/s) of pelvis velocity, minus the commanded velocity. */
  static gain = 1.5;

  override command(s: ReflexState, base: ArrayLike<number>, out: Float64Array): void {
    const q = s.qpos, v = s.qvel;
    const w = q[3] as number, x = q[4] as number, y = q[5] as number, z = q[6] as number;
    const yaw = Math.atan2(2 * (w * z + x * y), 1 - 2 * (y * y + z * z));
    const c = Math.cos(yaw), sn = Math.sin(yaw);
    const vwx = v[0] as number, vwy = v[1] as number;
    const vbx = c * vwx + sn * vwy;
    const vby = -sn * vwx + c * vwy;
    const g = KiroReflex.gain;
    out[0] = (base[0] as number) + g * (vbx - (base[0] as number));
    out[1] = (base[1] as number) + g * (vby - (base[1] as number));
    out[2] = base[2] as number;
  }
}
